import{c as e,Q as o,j as r,m as a}from"./chunks/framework.BXc4yaFE.js";const g=JSON.parse('{"title":"The Harness Is The Product","description":"","frontmatter":{},"headers":[],"relativePath":"research/tweets/2026-06-08-@dongxi_nlp-163124.md","filePath":"research/tweets/2026-06-08-@dongxi_nlp-163124.md","lastUpdated":1785909234000}'),s={name:"research/tweets/2026-06-08-@dongxi_nlp-163124.md"};function l(n,t,i,d,c,p){return o(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="the-harness-is-the-product" tabindex="-1">The Harness Is The Product <a class="header-anchor" href="#the-harness-is-the-product" aria-label="Permalink to &quot;The Harness Is The Product&quot;">​</a></h1><p><strong>作者</strong>：马东锡 NLP (@dongxi_nlp)<br><strong>發布時間</strong>：2026-06-08<br><strong>原始連結</strong>：<a href="https://x.com/dongxi_nlp/status/2064098727867163124" target="_blank" rel="noreferrer">https://x.com/dongxi_nlp/status/2064098727867163124</a><br><strong>類型</strong>：Twitter Article（簡體中文）<br><strong>統計</strong>：❤️ 149 · 🔁 35 · 🔖 247 · 👁 29,749</p><hr><h2 id="分析摘要" tabindex="-1">分析摘要 <a class="header-anchor" href="#分析摘要" aria-label="Permalink to &quot;分析摘要&quot;">​</a></h2><p><strong>TL;DR</strong>：「Model 只做 Proposal，Harness 負責 Decision」——Coding Agent 六大核心組件（live repo context / prompt shape / structured tools / context reduction / transcripts+memory / delegation）的工程設計深度拆解；「Harness is the product」作為工程準則，而非 slogan。</p><h3 id="核心論點" tabindex="-1">核心論點 <a class="header-anchor" href="#核心論點" aria-label="Permalink to &quot;核心論點&quot;">​</a></h3><ol><li><strong>Model 做 Proposal，Harness 做 Decision（最關鍵命題）</strong>：每一個 tool call 背後，harness 要回答的不是「執行」而是「決策列表」（路徑安全、是否 overwrite、讀取是否過期、是否需要 approval、output 截取量等）——這些判斷不能交給 model 的隨機處理</li><li><strong>六大組件</strong>： <ul><li><strong>Live repo context</strong>：agent 需知道 workspace、當前文件、project docs、哪些 state 可暴露</li><li><strong>Prompt shape</strong>：context quality 往往看起來像 model quality；stable prefix + clear tool contract + controlled history</li><li><strong>Structured tools</strong>：tools = model proposal 與 real side effects 之間的 contract（解析→驗證→檢查 policy→執行→裁剪 output→記錄）</li><li><strong>Context reduction</strong>：好 context 是 projection，非不斷膨脹的 blob</li><li><strong>Transcripts and memory</strong>：transcript 回答「發生了什麼」；working state 回答「現在什麼重要」——兩份任務，分別對待</li><li><strong>Delegation</strong>：subagents = 有邊界的 workers（scoped tools + isolated state + distilled results）；當 delegation 充當 context firewall 才真正有用</li></ul></li><li><strong>Harness 擁有 loop，Model 在 loop 裡面</strong>：<code>observe-act loop</code> 有價值的部分發生在 observe 和 act 之間，這是 harness 的域</li><li><strong>Failure → Diagnostic 對應表</strong>：重複行為→loop+retry policy；編輯 stale code→file-state baselines；越跑越差→context projection；意外操作→permission policy；無法從 tool error 恢復→tool result objects</li></ol><h3 id="批判性觀察" tabindex="-1">批判性觀察 <a class="header-anchor" href="#批判性觀察" aria-label="Permalink to &quot;批判性觀察&quot;">​</a></h3><ol><li>中文技術文章，受眾精準，觀點清晰但無實驗數據</li><li>六組件框架與 Anthropic 官方 dynamic workflows 文章高度互補（micro vs macro 兩個粒度）</li><li>「Stale Read Trap」預告下篇，說明系列連載，有後續內容</li></ol><hr><h2 id="評分" tabindex="-1">評分 <a class="header-anchor" href="#評分" aria-label="Permalink to &quot;評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>理由</th></tr></thead><tbody><tr><td>A. Workspace 可行動性</td><td>8/10</td><td>六組件框架可直接對照 cc-workspace harness 設計；failure→diagnostic table 可作 debug checklist</td></tr><tr><td>B. 創新性</td><td>7/10</td><td>harness-vs-model 角色切割的 crisp formulation；tool = proposal-to-side-effects contract 是新穎角度</td></tr><tr><td>C. 證據品質</td><td>7/10</td><td>工程分析清晰、有具體反例（write tool call decision list）；無量化數據</td></tr><tr><td>D. 技術深度</td><td>8/10</td><td>每組件有操作細節；naive agent failure modes 列舉全面</td></tr><tr><td>E. 泛化性</td><td>9/10</td><td>框架適用所有 coding agent harness，非 Claude/cc-workspace 專屬</td></tr><tr><td><strong>加權總分</strong></td><td><strong>7.75/10</strong></td><td>A×0.3 + B×0.2 + C×0.2 + D×0.15 + E×0.15</td></tr></tbody></table><p><strong>整合決策</strong>：Rule<br><strong>整合位置</strong>：<code>core.md</code> OBSERVE 段：「Harness 做 Decision，Model 做 Proposal」；subagent-strategy.md：delegation = context firewall；failure→diagnostic 對應表入 refs/harness-meta<br><strong>整合狀態</strong>：待實作</p><hr><h2 id="全文" tabindex="-1">全文 <a class="header-anchor" href="#全文" aria-label="Permalink to &quot;全文&quot;">​</a></h2><p>为什么 coding agent 最重要的部分，常常是最不显眼的那部分。</p><p>每次讨论 coding agent，大家最后都会从 model 开始。&quot;用哪个 model？context 多大? 写代码能力怎么样？&quot;这些问题重要，但它们已经不再是我们应该最先问的问题，我们应该问的第一个问题应该是：</p><blockquote><p>Harness 到底负责什么？</p></blockquote><p>当我们回顾基础的 LLM 预测文本任务，reasoning model 可以跟随结构，输出 tool call，并在 protocol 里工作。coding agent 则更进一步：它把 model 放进一套 runtime。这个 runtime 能检查真实 repo，请求 tool，编辑文件，跑检查，记住发生过什么，并在多轮中继续推进。</p><blockquote><p>这层 runtime 就是 harness。对 coding agent 来说，harness 本身就是 product。</p></blockquote><h2 id="the-naive-version" tabindex="-1">The Naive Version <a class="header-anchor" href="#the-naive-version" aria-label="Permalink to &quot;The Naive Version&quot;">​</a></h2><p>一个 mini 版本的 coding agent 很快会出问题：</p><ul><li>当 model 要编辑一个它从没读过的文件，会发生什么？</li><li>当 shell command 触碰 workspace 外的文件，会发生什么？</li><li>当 tool 返回 50,000 行输出，会发生什么？</li><li>当文件已经在磁盘上变化，transcript 里仍然保留旧 file read，会发生什么？</li><li>当 tool result 和产生它的 tool call 对不上，会发生什么？</li></ul><p>这个 system 还没有成为 coding agent。</p><h2 id="what-the-harness-owns" tabindex="-1">What The Harness Owns <a class="header-anchor" href="#what-the-harness-owns" aria-label="Permalink to &quot;What The Harness Owns&quot;">​</a></h2><p>Model 可以提出 proposal，Harness 负责做决定。</p><h2 id="six-things-a-coding-agent-harness-must-do" tabindex="-1">Six Things A Coding-Agent Harness Must Do <a class="header-anchor" href="#six-things-a-coding-agent-harness-must-do" aria-label="Permalink to &quot;Six Things A Coding-Agent Harness Must Do&quot;">​</a></h2><ol><li><p><strong>Live repo context</strong>：Agent 不该从空 prompt 开始。它需要知道 workspace、当前文件、相关 project docs，以及哪些 repo state 可以安全暴露。</p></li><li><p><strong>Prompt shape</strong>：Context quality 经常看起来像 model quality。稳定的 prefix、清晰的 tool contract、当前 request、受控的 history，带来的行为差异可能比换 model 更大。</p></li><li><p><strong>Structured tools</strong>：Tools 不应被当作 helper functions。它们是 model proposal 和真实 side effects 之间的 contract。Harness 解析 arguments，验证 paths，检查 policy，执行操作，裁剪 output，并记录发生了什么。</p></li><li><p><strong>Context reduction</strong>：如果 harness 盲目追加所有东西，model 最后会看到太多、太少，或者看到错误的东西。好的 context 是一个 projection，而非不断膨胀的 blob。</p></li><li><p><strong>Transcripts and memory</strong>：Transcript 回答：&quot;发生过什么？&quot; Working state 回答：&quot;现在什么重要？&quot;这是两份不同的任务，当然需要区别对待。</p></li><li><p><strong>Delegation</strong>：Subagents 也不等于 magic parallelism。它们应该是有边界的 workers：scoped tools、isolated state、distilled results。当 delegation 充当 context firewall 时，它才真正有用。</p></li></ol><h2 id="the-main-loop" tabindex="-1">The Main Loop <a class="header-anchor" href="#the-main-loop" aria-label="Permalink to &quot;The Main Loop&quot;">​</a></h2><p>coding agent 是一个 observe-act loop，但真正有价值的部分，发生在 observe 和 act 之间。model 在 loop 里面，harness 拥有 loop。这个区别很关键。</p><h2 id="a-concrete-example" tabindex="-1">A Concrete Example <a class="header-anchor" href="#a-concrete-example" aria-label="Permalink to &quot;A Concrete Example&quot;">​</a></h2><p>假设 model 发出一个 tool call（write to src/config.py），harness 需要回答：</p><ul><li>src/config.py 是否在 workspace 内？</li><li>这个 path 是否会通过 symlink 逃逸？</li><li>这是新文件，还是 overwrite？</li><li>model 最近是否读过现有文件？</li><li>已知的 file baseline 是否过期？</li><li>这次 write 是否需要 human approval？</li><li>edit result 是否应该包含 diff summary？</li><li>后面是否应该跑 validation command？</li><li>有多少 output 应该进入下一轮 prompt？</li><li>需要更新哪些 state，避免下一轮 stale？</li></ul><p>这些判断不该交给 model 的随机处理。Prompt 可以描述期望行为。Harness 负责落实边界。</p><h2 id="the-product-lesson" tabindex="-1">The Product Lesson <a class="header-anchor" href="#the-product-lesson" aria-label="Permalink to &quot;The Product Lesson&quot;">​</a></h2><p>一旦你开始看见 harness，很多 coding-agent 行为都会更容易诊断。</p><ul><li>如果 agent 不断重复，去检查 loop 和 retry policy。</li><li>如果它编辑 stale code，去检查 file-state baselines。</li><li>如果它越跑越差，去检查 context projection。</li><li>如果它运行了意外的东西，去检查 permission policy。</li><li>如果它无法从 tool errors 中恢复，去检查 tool result objects。</li><li>如果它解释不清发生了什么，去检查 traces、audit、doctor surfaces。</li></ul><p>model 当然重要，只是 model quality 只占其中一层。真正的 agent experience 来自 model 周围的整套 harness。这就是为什么 &quot;the harness is the product&quot; 不只是一句 slogan。它是一条工程规则：</p><blockquote><p>Anything that must be reliable belongs in the harness.</p></blockquote>',39)])])}const u=e(s,[["render",l]]);export{g as __pageData,u as default};
